"""Offline deck/window selector backed by completed tournament simulations."""
from pathlib import Path
import json,csv,html,math
import numpy as np
from plotly.offline import get_plotlyjs
ROOT=Path(__file__).resolve().parents[1];DATA=ROOT/'data/processed';RES=ROOT/'results/general'
def native(x):
 if isinstance(x,np.ndarray):return x.tolist()
 if isinstance(x,np.generic):return x.item()
 raise TypeError(type(x))
def main():
 manifest=json.loads((RES/'manifest.json').read_text());completion=json.loads((RES/'completion.json').read_text());m30=np.load(DATA/'model30.npz');names=list(m30['names']);payload={'names':names,'windows':{},'decks':{},'total':completion['tournaments']}
 for days in [30,45]:
  m=np.load(DATA/f'model{days}.npz');payload['windows'][str(days)]={k:m[k] for k in ['counts','win','draw','W','D']}
 for s in manifest['scenarios']:
  with np.load(RES/(s['id']+'.npz')) as z:
   if 'target' in s:continue
   deck=str(s['deck']);days=str(s['days']);payload['decks'].setdefault(deck,{'name':s['name'],'windows':{},'improvements':[]})
   d={k:z[k] for k in ['totals','seen','losses','records','paths','spy_top','batch_rates']}
   d['byround']=z['exposure'].sum(axis=(0,2));d['exposure']=z['exposure'].sum(axis=0)
   payload['decks'][deck]['windows'][days]=d
 for s in manifest['scenarios']:
  if 'target' not in s:continue
  q=np.load(RES/(s['id']+'.npz'));deck=payload['decks'][str(s['deck'])];base=np.array(deck['windows']['30']['batch_rates'])[:len(q['batch_rates'])];diff=q['batch_rates']-base
  deck['improvements'].append({'target':s['target'],'name':s['target_name'],'n':int(q['totals'][5]),'rate':float(q['totals'][0]/q['totals'][5]),'delta':float(diff.mean()),'error':float(1.96*diff.std(ddof=1)/len(diff)**.5)})
 events=list(csv.DictReader((DATA/'events_accepted.csv').open()));audit=json.loads((DATA/'audit_summary.json').read_text());payload['audit']=audit
 options=''.join(f'<option value="{i}">{html.escape(d["name"])}'+(' · categoría agregada' if d['name'] in ['Other','Unknown'] else '')+'</option>' for i,d in sorted(payload['decks'].items(),key=lambda x:x[1]['name']))
 css='''*{box-sizing:border-box}body{margin:0;background:#f1f1eb;color:#243843;font:15px/1.65 Arial,sans-serif}main{max-width:1240px;margin:auto;padding:40px 26px 70px}.eyebrow{letter-spacing:3px;color:#176d81;font-size:12px;font-weight:700}h1{font-size:clamp(40px,6vw,70px);letter-spacing:-2px;line-height:1.05;margin:20px 0}h2{font-size:26px;line-height:1.2;margin:42px 0 15px}.lead{font-size:19px;color:#617078}.controls{display:flex;gap:20px;flex-wrap:wrap;position:sticky;top:0;z-index:5;padding:17px 20px;background:#fffdf8;border-bottom:3px solid #176d81;box-shadow:0 6px 10px #00000008}label{font-size:12px;font-weight:700;display:grid;gap:3px}select{padding:9px;font-size:16px;border:1px solid #bcc9c9;border-radius:4px;background:white;color:#243843;max-width:100%}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));gap:14px;margin:24px 0}.card{padding:20px;background:#fffdf8;border-top:3px solid #176d81}.card strong{display:block;color:#176d81;font-size:34px}.card small{display:block;color:#617078}.notice{background:#fff7e4;padding:18px 22px;border-left:4px solid #d3a04a;margin:22px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.chart{background:#fffdf8;min-width:0;min-height:430px}.tablewrap{overflow-x:auto;max-height:650px;background:#fffdf8;margin:16px 0}table{border-collapse:collapse;font-size:13px;width:100%}th{position:sticky;top:0;text-align:left;background:#dfe8e6;padding:11px;white-space:nowrap}td{padding:9px 11px;border-bottom:1px solid #e5e8e2}tr:hover td{background:#f3f6f2}a{color:#176d81}small{color:#617078}code{font-size:12px;background:#e2e7e1;padding:2px 5px}.metricsnote{font-size:13px;color:#617078}details{margin:22px 0;padding:16px 20px;background:#fffdf8}summary{cursor:pointer;font-weight:bold}.context{color:#176d81;font-size:18px;font-weight:bold}.empty{padding:30px;color:#617078}footer{margin-top:50px;font-size:13px;color:#617078}@media(max-width:760px){.grid{grid-template-columns:1fr}.controls{position:static}main{padding:25px 14px}h1{letter-spacing:-1px}.chart{min-height:400px}}'''
 body='''<div class="eyebrow">MONTE CARLO · TORNEOS PRESENCIALES</div><h1>Tu mazo,<br>sus caminos al top 8.</h1><p class="lead">Elegí un arquetipo y explorá sus rivales, probabilidades y puntos de preparación.</p><div class="controls"><label>Tu mazo<select id="deck">OPTIONS</select></label><label>Datos de papel<select id="window"><option value="30">Últimos 30 días · principal</option><option value="45">Últimos 45 días · comparación</option></select></label><label>Próxima ronda<select id="round"></select></label><label>Puntos antes de jugar<select id="points"></select></label></div><p class="context" id="context"></p><div id="cards" class="cards"></div><div id="coverage" class="notice"></div><p class="metricsnote">P(top 8) es una estimación del modelo para tu plaza reservada. IC95% MC mide únicamente azar de simulación. La muestra y los supuestos pueden causar errores mayores. No se modelan ID, drops, diferencias de habilidad ni byes.</p><div id="insight" class="notice"></div><h2>El field y tus matchups</h2><div class="grid"><div id="meta" class="chart"></div><div id="wr" class="chart"></div></div><div id="matchups"></div><h2>Cómo se desarrollan las rondas</h2><div class="grid"><div id="rounds" class="chart"></div><div id="state" class="chart"></div></div><p class="metricsnote">Los filtros de ronda y puntos afectan al gráfico de próximo rival. Los demás resultados describen el torneo completo. Un estado por puntos puede incluir varios récords W/L/D.</p><div id="encounters"></div><h2>Clasificados y eliminados</h2><div class="grid"><div id="records" class="chart"></div><div id="losses" class="chart"></div></div><p id="elimination"></p><div id="paths"></div><h2>Qué cruces vale la pena preparar</h2><p>Intervenciones calculadas con datos de 30 días: +5 puntos de WR decisivo de todos los pilotos de tu arquetipo contra un rival. Se conservan empates y se recalculan los emparejamientos. No es evidencia de que una carta o un cambio de sideboard produzca esa mejora.</p><div id="improvement" class="chart"></div><div id="improvementTable"></div><p class="metricsnote">Las diferencias se comparan con los primeros 25.000 torneos centrales de semillas compartidas. Intervalos amplios pueden incluir cero: no concluir una mejora si el ruido no permite distinguirla. La intervención mejora un cruce sin costos en otros, un supuesto que exige testing con una lista real.</p><h2>Comparación entre ventanas y representación del mazo</h2><div class="grid"><div id="windows" class="chart"></div><div id="topcount" class="chart"></div></div><p class="metricsnote">La cantidad de clasificados del arquetipo se mide en torneos donde tu plaza ya está reservada para ese arquetipo. No equivale a un field sin plaza forzada.</p><details><summary>Muestra, modelo y límites</summary><div id="method"></div></details><details><summary>Eventos presenciales aceptados y fuentes primarias</summary>EVENTS</details><details><summary>Comparar todos los arquetipos del selector</summary><p>Ordenados alfabéticamente. Las tasas son condicionales al modelo; no constituyen un ranking de calidad ni incorporan la experiencia de cada piloto.</p><div id="compare"></div></details><p><a href="spy_montecarlo.html">Ver el estudio detallado de Spy y su corrida original de 5 millones →</a></p><footer>Informe autónomo: selector, gráficos y datos funcionan sin conexión. Corte: 19/10/2026. Las simulaciones del selector se ejecutaron además del estudio original de Spy; no se suman escenarios diferentes para formar una única probabilidad.</footer>'''.replace('OPTIONS',options)
 eventshtml='<div class="tablewrap"><table><thead><tr><th>Evento</th><th>Fecha</th><th>Sede</th><th>Plazas</th><th>Matches</th></tr></thead><tbody>'+''.join(f'<tr><td><a target="_blank" rel="noreferrer" href="{e["url"]}">{html.escape(e["name"])}</a></td><td>{e["date"]}</td><td>{html.escape(e["venue"])}</td><td>{e["players"]}</td><td>{e["matches"]}</td></tr>' for e in sorted(events,key=lambda e:e['date'],reverse=True))+'</tbody></table></div>'
 body=body.replace('EVENTS',eventshtml)
 js=(ROOT/'src/dashboard.js').read_text()
 out='<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Metajuego en papel · Simulador de top 8</title><style>'+css+'</style><script>'+get_plotlyjs()+'</script></head><body><main>'+body+'</main><script>const DATA='+json.dumps(payload,default=native,separators=(',',':')).replace('</','<\\/')+';</script><script>'+js+'</script></body></html>'
 (ROOT/'reports/metagame_explorer.html').write_text(out);(ROOT/'results/general/summary.json').write_text(json.dumps({'decks':len(payload['decks']),'tournaments':completion['tournaments'],'charts':9},indent=2));print('general report',len(payload['decks']),'deck choices',len(out),'bytes',flush=True)
if __name__=='__main__':main()
